import { useEffect, useRef, useState, type ChangeEvent, type ReactNode, type ButtonHTMLAttributes, type CSSProperties } from 'react';
import { Link, useLocation } from 'wouter';
import type { LucideIcon } from 'lucide-react';
import {
  ArrowRight, BookOpen, CalendarDays, ChevronLeft, ChevronRight,
  ClipboardList, Cloud, Download, FileText, Flag, GraduationCap, Heart, Home, Leaf, Menu,
  NotebookPen, Pencil, Plus, Printer, RotateCcw, Search, Settings2,
  Sparkles, Target, Trash2, TrendingUp, Upload, UserRound, Zap
} from 'lucide-react';
import { downloadPlannerPdf } from './pdf-export';

type Profile = { name: string; college: string; course: string; branch: string; semester: string; year: string; roll: string; email: string };
type Subject = { id: string; name: string; faculty: string; credits: number; target: string; current: string; progress: number; notes: string };
type Goal = { id: string; category: string; title: string; description: string; date: string; progress: number; completed: boolean };
type Assignment = { id: string; subject: string; title: string; description: string; due: string; priority: string; status: string; submitted: boolean };
type Exam = { id: string; subject: string; date: string; time: string; topics: string; progress: number; revisions: boolean[] };
type Habit = { id: string; name: string; days: number[] };
type ImportantDate = { id: string; title: string; type: string; date: string; note: string };
type PlannerState = {
  profile: Profile; subjects: Subject[]; goals: Goal[]; assignments: Assignment[]; exams: Exam[];
  habits: Habit[]; importantDates: ImportantDate[]; habitMonth: string; timetable: Record<string, string>;
  weekly: Record<string, string>; daily: { date: string; priorities: string[]; notes: string; achievements: string };
  monthly: { month: string; goals: string; notes: string }; grades: Record<string, number[]>;
  revisions: Record<string, { topic: string; checks: boolean[]; confidence: string }[]>; notes: { id: string; title: string; body: string }[];
  reflection: Record<string, string>;
};

const uid = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const dayISO = (add: number) => { const d = new Date(); d.setDate(d.getDate() + add); return d.toISOString().slice(0, 10); };
const todayISO = () => new Date().toISOString().slice(0, 10);

